// Chapter 7, batch 4 (the last words, the fire and the epilogue) cutscene stills, drawn with PixelLab, one per storyboard shot (storyboard/ch7, boards 07 and 08).
// Each cutscene is one sheet, assets/img/cut/<cutscene>.webp, its 16:9 shots stacked top to bottom. A shot plays
// under the first line holding its cue (js/vn.js, addShots). Generated by the cutscene pipeline
// (/mnt/project-files/cutscenes/pixellab/); change the spec there and re-export rather than editing this file.
(function () {
  const CUTS = [
    ['c7-last', ["Root is denied, her sessions are revoked", "You answered. That's the worst thing", "I'm not going to unmake you", "You let me choose. I'm choosing now.", "Sit. No, the other chair.", "In the log, a StartRestoreJob", "Afterwards, Kagemaru counts his payment"]],
    ['c7-lastvault', ["In Kagemaru's vault, he's sitting beside", "He would sell it to her in a heartbeat"]],
    ['c7-queue', ["What's left of her is her backup", "So Uptima attaches one more service control policy", "Freya ends as the one message", "Then it stops."]],
    ['c7-fireside', ["Uptima doesn't take the throne back", "Each band its own account, under the organization", "The camp's network shared across them", "Then she moves the prayers out of the queue", "And I won't work from the management account", "She reads some every night"]],
    ['c7-epi', ["The marsh cat's name is settled by Kyu", "No."]],
    ['c7-epifire', ["Kyu sits by the fire with Uptima", "IAM Identity Center.", "finds one of Freya's satisfaction cards"]],
    ['c7-ends', [["Hale is sorting letters", "Hale was never"], "Hale was never reckoned with", "Selvaria eats at the long table", "Selvaria was never reckoned with", "Namgung Hyeon hands back", "Namgung was never reckoned with", "Iris Vell sits in the Arcanum", "Iris was never reckoned with"]],
    ['c7-epidawn', ["Aurelian comes up out of the Abyss", "Tilly visits the camp", "Mira watches her go", "Uptima opens the way back", "The four watch the way close", "Kagemaru opens a stall at the edge of the camp", "in a napkin with his name spelled wrong", "Kagemaru's vault stays shut"]],
    ['c7-epiend', ["On the management account's console, the croissant is gone"]]
  ];
  // [cutscene, cues, glitch, ghosts]: glitch lists the shots (from 1) with a painted twin, assets/img/cut/<cutscene>-<n>-painted.webp;
  // ghosts maps a shot to a figure laid over it that floats: [sprite, centre x, top y, height], in % of the shot.
  CUTS.forEach(([cut, cues, glitch = [], ghosts = {}]) => {
    const ids = cues.map((c, i) => 'cut-' + cut + '-' + (i + 1));
    const ghost = g => g && { src: 'assets/img/cut/' + g[0] + '.webp', x: g[1], y: g[2], h: g[3] };
    SD.vn.addScenes(Object.fromEntries(ids.map((id, i) => [id, { sheet: 'assets/img/cut/' + cut + '.webp', frame: i, frames: ids.length, label: id,
      glitch: glitch.includes(i + 1) ? 'assets/img/cut/' + cut + '-' + (i + 1) + '-painted.webp' : undefined, ghost: ghost(ghosts[i + 1]) }])));
    SD.vn.addShots(ids.map((id, i) => [id, cues[i]]));
  });
})();
